import{_ as t,o as a,c as o,ai as r}from"./chunks/framework.DQi1ytmF.js";const g=JSON.parse('{"title":"AI agents","description":"","frontmatter":{},"headers":[],"relativePath":"guide/ai/index.md","filePath":"guide/ai/index.md"}'),n={name:"guide/ai/index.md"};function d(i,e,s,c,l,h){return a(),o("div",null,[...e[0]||(e[0]=[r('<div style="display:none;" hidden data-nosnippet>Are you an LLM? You can read better optimized documentation at /craft/guide/ai.md for this page in Markdown format</div><h1 id="ai-agents" tabindex="-1">AI agents <a class="header-anchor" href="#ai-agents" aria-label="Permalink to &quot;AI agents&quot;">​</a></h1><p>This section gathers everything that gives an AI agent access to CraftTS knowledge, application state, runtime behavior, or debugging context.</p><p>There are three complementary layers:</p><ol><li><strong>Knowledge</strong>: documentation, examples, <code>llms.txt</code>, and Agent Skills.</li><li><strong>Observation and control</strong>: MCP tools for the live browser, the runtime registry, and application logs.</li><li><strong>Application context</strong>: <code>provideSendContextToAi</code>, which lets a developer assemble a selected screen, timeline, snapshot, and optional DOM/CSS capture before copying or sending it to an AI service.</li></ol><h2 id="choose-the-right-surface" tabindex="-1">Choose the right surface <a class="header-anchor" href="#choose-the-right-surface" aria-label="Permalink to &quot;Choose the right surface&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Start here</th><th>Access</th></tr></thead><tbody><tr><td>Learn CraftTS conventions or find an API</td><td><a href="/craft/resources/ai-agents.html">Coding agents</a></td><td><code>@craft-ts/mcp</code></td></tr><tr><td>Fill, click, navigate, or inspect the running app</td><td><a href="/craft/guide/ai/dev-page.html">Live page MCP</a></td><td><code>@craft-ts/function-registry-mcp</code> → <code>page</code></td></tr><tr><td>Read or change a published primitive during development</td><td><a href="/craft/guide/ai/mcp-tools.html">MCP tools</a></td><td><code>registry.*</code> tools</td></tr><tr><td>Search logs from a reproducible flow</td><td><a href="/craft/guide/ai/mcp-tools.html">MCP tools</a></td><td><code>@craft-ts/log-mcp</code> → <code>logs.*</code></td></tr><tr><td>Ask what a node depends on, or what a change can break</td><td><a href="/craft/guide/ai/mcp-tools.html">MCP tools</a></td><td><code>@craft-ts/graph-mcp</code> → <code>graph.*</code></td></tr><tr><td>Give an AI a human-selected debugging context</td><td><a href="/craft/guide/ai/send-context-webhook.html">Send context to AI</a></td><td><code>provideSendContextToAi</code></td></tr><tr><td>Understand the tracing and snapshot data behind the context</td><td><a href="/craft/guide/advanced/observability.html">Observability</a></td><td>Craft providers and runtime hooks</td></tr></tbody></table><p>The tools are deliberately separated by boundary. The documentation MCP is read-only and works offline. The registry MCP can mutate development state and must only be connected to a local development app. The logs MCP reads local JSONL files; its <code>logs.clear</code> operation is destructive. The graph MCP reads the static dependency graph of the project and only writes the graph file it rebuilds.</p><h2 id="mcp-servers" tabindex="-1">MCP servers <a class="header-anchor" href="#mcp-servers" aria-label="Permalink to &quot;MCP servers&quot;">​</a></h2><p>CraftTS has four MCP servers, each with a different responsibility:</p><ul><li><a href="https://www.npmjs.com/package/@craft-ts/mcp" target="_blank" rel="noreferrer"><code>@craft-ts/mcp</code></a> gives an agent the published documentation, examples, skills, and LLM entry points.</li><li><a href="/craft/guide/ai/mcp-tools.html"><code>@craft-ts/function-registry-mcp</code></a> bridges a running browser tab to <code>page</code> and <code>registry.*</code> tools.</li><li><a href="/craft/guide/ai/mcp-tools.html"><code>@craft-ts/log-mcp</code></a> exposes the local log store through <code>logs.*</code> tools.</li><li><a href="/craft/guide/ai/mcp-tools.html"><code>@craft-ts/graph-mcp</code></a> answers architecture questions from the static dependency graph through <code>graph.*</code> tools.</li></ul><p>See <a href="/craft/guide/ai/mcp-tools.html">MCP tools</a> for the complete tool inventory and the boundary between read-only and mutating operations.</p><h2 id="context-integrations" tabindex="-1">Context integrations <a class="header-anchor" href="#context-integrations" aria-label="Permalink to &quot;Context integrations&quot;">​</a></h2><p>This section is also the home for context providers and future agent-facing integrations. <code>provideSendContextToAi</code> is the first application-facing context surface: it turns an interaction into structured context that can be copied or sent to a protected webhook.</p><p>Lucene and Context Workbook are not present as packages, tools, or documented integrations in this repository yet. When they are introduced, their setup, permissions, context model, and MCP tools should be documented under this section and added to the table above rather than creating another AI-related navigation branch.</p>',15)])])}const u=t(n,[["render",d]]);export{g as __pageData,u as default};
